import{state}from"./state.js";import{renderAll,renderRequests}from"./ui.js";import{showToast,showConfirm,showMobileEventNotification,escapeHtml}from"./utils.js";import{scheduleSave,addHistoryEntry,checkLimits,getActingChildId,updateBalanceLocally,addRequestEntry}from"./action-helpers.js";import{triggerPurchaseAnimation}from"./motion-feedback.js";function getShopLimitToastMessage(e){return e?e.startsWith("Месячный лимит")?`Превышен месячный лимит. ${e}`:e.startsWith("Лимит на крупные покупки")?`Уже была крупная покупка. ${e}`:e.startsWith("Лимит (")?`Лимит частоты. ${e}`:e:"Лимит исчерпан"}function applyPurchase(e,t,i){updateBalanceLocally(t,-e.price),addHistoryEntry({type:"spend",amount:e.price,description:e.name,group:e.group,comment:e.comment,relatedId:e.id,moneyAmount:i,childIdOverride:t}),scheduleSave(),renderAll(),showMobileEventNotification(`Вы купили: ${e.name}!`,"success","Balance updated"),triggerPurchaseAnimation()}function sendPurchaseRequest(e,t,i){addRequestEntry({childId:t,requestType:"shop_purchase",itemId:e.id,taskId:e.id,taskName:e.name,coins:e.price,moneyAmount:i}),scheduleSave(),renderRequests(),document.querySelector('.nav__btn[data-tab="requests"]')?.click(),showMobileEventNotification("Заявка на покупку отправлена","success","Новая заявка"),triggerPurchaseAnimation()}function getBuyItemError(e){return e?0===state.children.length?"Сначала добавьте ребенка":"Сначала выберите ребенка":"Товар не найден"}export function buyItem(e){const t=state.shopItems.find(t=>t.id==e),i=getActingChildId();if(!t||!i)return showToast(getBuyItemError(t),"error");if(state.balance<t.price)return showToast("Недостаточно монет!","error");const r=t.moneyLimit||t.money_limit||0,s=checkLimits(t,r,{childIdOverride:i});if(s){if(state.isAdmin){const e=`${s}. Все равно ${state.isAdmin?"купить":"отправить заявку"}?`;return showConfirm("Лимит превышен",e,{onConfirm:()=>confirmPurchase(t,i,{mLimit:r,limitWarned:!0})})}return showToast(getShopLimitToastMessage(s),"error")}confirmPurchase(t,i,{mLimit:r})}function confirmPurchase(e,t,i={}){const{mLimit:r,limitWarned:s}=i,n=s?"Подтвердите (лимит превышен)":state.isAdmin?"Подтвердите покупку":"Отправить заявку?";let o=state.isAdmin?`Купить "${escapeHtml(e.name)}" за ${e.price}`:`"${escapeHtml(e.name)}" за ${e.price}`;o+=' <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>',r>0&&(o+=`<br><span style="font-size: 0.9em; color: var(--color-text-muted);">Лимит: 💶 ${r}</span>`),state.isAdmin&&(o+="?"),state.isAdmin?showConfirm(n,o,{onConfirm:()=>applyPurchase(e,t,r)}):showConfirm(n,o,{onConfirm:()=>sendPurchaseRequest(e,t,r)})}